// ✅ DUNG: tim ra TRUOC, ra khoi vong lap roi moi xoa
public boolean deleteDoctor(DoctorRequestDTO requestDTO) throws Exception {
    Doctor doctor = findByCode(requestDTO.getCode());

    // khong co ma nay: khong xoa gi
    if (doctor == null) {
        return false;
    }

    return doctorList.remove(doctor);
}

